  'structurizr.inspection.element.orphan.severity',
  'structurizr.inspection.element.orphan',
  'structurizr.inspection.disconnectedElement.severity',
  'structurizr.inspection.disconnectedElement',
];

// Test each candidate individually to isolate which one works
const results = [];
for (const cand of candidates) {
  const dsl = buildDsl(`            "${cand}" "ignore"`);
