  'structurizr.inspection.documentation.severity',
  'structurizr.inspection.decisions.severity',
];

const results = [];
for (const cand of candidates) {
  const res = await tools.structurizr.inspect({ dsl: buildDsl(`            "${cand}" "ignore"`) });
  const cats = res.map(e => {
    if (/missing documentation/i.test(e)) return 'documentation';
    if (/missing decisions/i.test(e)) return 'decisions';
    if (/disconnected/i.test(e)) return 'disconnected';
    return null;
  }).filter(Boolean);
  results.push({ candidate: cand, remaining: cats });
}
return { baseline: baseCats, results };

