metadata.rawInput:
{"code": "function buildDsl(propsLines) {
  return `workspace "Test" "desc" {
    model {
        properties {
${propsLines}
        }
        s = softwareSystem "S" "d" {
            c = container "C" "d" "Tech"
        }
    }
    configuration {
        scope softwaresystem
    }
}`;
}

function categorize(e) {
  if (/missing documentation/i.test(e)) return 'documentation';
  if (/missing decisions/i.test(e)) return 'decisions';
  if (/disconnected/i.test(e)) return 'disconnected';
  return null;
}

const candidates = [
  'structurizr.inspection.Container.disconnected.severity',
  'structurizr.inspection.SoftwareSystem.documentation.severity',
  'structurizr.inspection.SoftwareSystem.decisions.severity',
  'structurizr.inspection.container.disconnected.severity',
  'structurizr.inspection.softwareSystem.documentation.severity',
  'structurizr.inspection.softwareSystem.decisions.severity',
  'structurizr.inspection.element.disconnected.severity',
  'structurizr.inspection.disconnected.severity',
  'structurizr.inspection.documentation.severity',
  'structurizr.inspection.decisions.severity',
  'structurizr.inspection.element.disconnected',
  'structurizr.inspection.softwareSystem.documentation',
  'structurizr.inspection.softwareSystem.decisions',
];

const results = [];
for (const cand of candidates) {
  const res = await tools.structurizr.inspect({ dsl: buildDsl(`            "${cand}" "ignore"`) });
  const remaining = res.map(categorize).filter(Boolean);
  results.push({ candidate: cand, remaining });
}
return results;"}
